  "    toastTimer = setTimeout(function () { host.hidden = true; }, 6000);",
  "  }",
  "",
  "  // ---- the song library ------------------------------------------------",
  "",
  "  function bootLibrary() {",
  "    var listHost = page.querySelector('[data-role=songs]');",
  "    var filter = page.querySelector('[data-role=project-filter]');",
  "    var form = page.querySelector('[data-act=new-song]');",
  "",
  "    function renderSongs(songs) {",
  "      if (!listHost) return;",
  "      clear(listHost);",
  "      if (!songs.length) {",
  "        listHost.appendChild(el('p', 'st-empty-note', 'No songs here yet. Create one below.'));",
  "        return;",
  "      }",
  "      for (var i = 0; i < songs.length; i += 1) {",
  "        var song = songs[i] || {};",
  "        var link = el('a', 'st-song');",
  "        link.href = '/dashboard/studio?song=' + encodeURIComponent(String(song.id || ''));",
  "        link.appendChild(el('span', 'st-song-title', song.title || 'Untitled song'));",
  "        link.appendChild(el('span', 'st-song-meta', 'updated ' + relativeTime(song.updated_at)));",
  "        listHost.appendChild(link);",
  "      }",
  "    }",
  "",
  "    function load() {",
  "      var projectId = filter && filter.value ? filter.value : '';",
  "      var url = '/api/studio/songs' + (projectId ? '?project_id=' + encodeURIComponent(projectId) : '');",
  "      fetch(url, { credentials: 'same-origin' })",
  "        .then(function (response) {",
  "          if (!response.ok) throw new Error('The song list could not be loaded.');",
  "          return response.json();",
  "        })",
  "        .then(function (songs) { renderSongs(Array.isArray(songs) ? songs : []); })",
  "        .catch(function (err) { toast(errorText(err)); });",
  "    }",
  "",
  "    if (filter) filter.addEventListener('change', load);",
  "",
  "    if (form) {",
  "      form.addEventListener('submit', function (event) {",
  "        event.preventDefault();",
  "        var titleInput = form.querySelector('[name=title]');",
  "        var projectSelect = form.querySelector('[name=project_id]');",
  "        var title = String((titleInput && titleInput.value) || '').trim();",
  "        var projectId = Number(projectSelect && projectSelect.value);",
  "        if (!title) { toast('A new song needs a title.'); return; }",
  "        if (!Number.isInteger(projectId)) { toast('Choose the project the song belongs to.'); return; }",
  "        var headers = { 'content-type': 'application/json' };",
  "        var token = cookie('crow_csrf');",
  "        if (token) headers['x-crow-csrf'] = token;",
  "        fetch('/api/studio/songs', {",
  "          method: 'POST',",
  "          credentials: 'same-origin',",
  "          headers: headers,",
  "          body: JSON.stringify({ project_id: projectId, title: title })",
  "        })",
  "          .then(function (response) {",
  "            return response.json().then(function (body) { return { status: response.status, body: body }; });",
  "          })",
  "          .then(function (result) {",
  "            if (result.status !== 200 || !result.body || !result.body.song_id) {",
  "              throw new Error((result.body && result.body.error) || 'The song could not be created.');",
  "            }",
  "            window.location.href = '/dashboard/studio?song=' + encodeURIComponent(result.body.song_id);",
  "          })",
  "          .catch(function (err) { toast(errorText(err)); });",
  "      });",
  "    }",
  "",
  "    load();",
  "",
  "    // The library holds no socket, no engine and no document, so it has",
  "    // nothing to tear down and is always safe to leave alone.",
  "    return { alive: function () { return true; }, teardown: function () {} };",
  "  }",
  "",
  "  // ---- one song --------------------------------------------------------",
  "",
  "  function bootStudio(activeSongId) {",
  "    var gridWrap = page.querySelector('[data-role=grid-wrap]');",
