  "    var historyHost = page.querySelector('[data-role=history]');",
  "    var presenceHost = page.querySelector('[data-role=presence]');",
  "    var titleHost = page.querySelector('[data-role=title]');",
  "    var bpmInput = page.querySelector('[data-role=bpm]');",
  "    var positionHost = page.querySelector('[data-role=position]');",
  "    var hintHost = page.querySelector('[data-role=hint]');",
  "    var timelineHost = page.querySelector('[data-role=timeline]');",
  "    var samplerHost = page.querySelector('[data-role=sampler]');",
  "    var mixerHost = page.querySelector('[data-role=mixer]');",
  "",
  "    var view = {",
  "      Y: null,",
  "      doc: null,",
  "      history: [],",
  "      presence: [],",
