  "      // launches it has collected so far.",
  "      mode: SESSION_VIEW,",
  "      dropDeck: false,",
  "      swallowClick: false,",
  "      placementId: null,",
  "      placementAuthors: {},",
  "      timelineBars: TIMELINE_MIN_BARS,",
