  "      takesOpen: {},",
  "      playhead: 0,",
  "      position: { bar: 1, beat: 1, sixteenth: 1 },",
  "      // The pattern each sampler track played at the engine's last position",
  "      // report (track id -> {pattern_id, slot_start_beat, slot_beats,",
  "      // chain_index}), or null until one has arrived. This is what the motion",
  "      // recorder writes into: the engine's own chain slot, not the page's",
  "      // estimate of it (see motionPlayingPattern). Cleared on a stop and on a",
  "      // new launch, so a new run never starts on the last run's pattern.",
  "      patterns: null,",
  "      recTimeline: { on: false, launches: [] },",
  "      // A performance the hub refused: the placements it was sent as and the",
  "      // cmd_id it went under, kept until Place what fits or Discard.",
  "      performance: null,",
  "      // The placement block that has the keyboard, so a render can put the",
  "      // focus back on the button it redraws.",
  "      focusedPlacement: null,",
  "      // The project bot the ask box talks to (null until the page knows one),",
  "      // the Perch session it opened, the session still being spawned, the SSE",
  "      // stream that session pushes on, whether that session has already been",
  "      // given the Studio context, and the last reply text drawn (so a text",
  "      // frame and the reply frame that repeats it draw one line).",
  "      projectBot: null,",
  "      askSession: null,",
  "      askStarting: null,",
  "      askStream: null,",
  "      askContextSent: false,",
  "      askLast: '',",
  "      // The sampler: the track whose kit the view is showing (a bank and a pad",
  "      // are chosen per kit), the pad a live press or key started, the samples",
  "      // the engine holds and the bytes this page keeps to reload one, the pad a",
  "      // recording is going into, and the resample in flight. snapToBar is the",
  "      // resample's Snap to bar box, on by default.",
  "      samplerTrack: '',",
  "      samplerBank: '',",
  "      samplerPad: 0,",
  "      // Whether the operator picked a pad themselves: only then does Loop to pad",
  "      // overwrite it, because an unpicked bank takes the first empty pad.",
  "      padPicked: false,",
  "      // Whether an effect or Looper button is being held from the keyboard, so",
  "      // the keyup knows to let it go.",
  "      fxKeyHeld: false,",
  "      padPress: null,",
  "      padKeys: {},",
  "      loadedSamples: {},",
  "      sampleLoading: {},",
  "      sampleFailures: {},",
  "      sampleBytes: {},",
  "      sampleInput: null,",
  "      sampleRec: null,",
