  "      var bank = bankOf(snap, track.id, view.samplerBank) || banks[0] || null;",
  "      return bank ? { track: track, bank: bank } : null;",
  "    }",
  "",
  "    function renderSampler(snap) {",
  "      if (view.closed || !samplerHost) return;",
  "      var clip = patternClipOf(snap);",
  "      var track = clip ? trackOf(snap, clip.track_id) : null;",
  "      if (!clip || !track) {",
  "        samplerHost.hidden = true;",
  "        clear(samplerHost);",
  "        return;",
  "      }",
  "      if (view.samplerTrack !== track.id) {",
  "        view.samplerTrack = track.id;",
  "        view.samplerBank = '';",
  "        view.samplerPad = 0;",
  "      }",
  "      // The waveform keeps one peak per pixel of the width it is drawn at, so",
  "      // a redraw measures the one on screen before it is replaced.",
  "      measureWaveWidth();",
  "      // Another clip is another set of patterns: the lane starts on the first",
  "      // pattern's first page, and no step is held over from the old one.",
  "      if (view.samplerClip !== clip.id) {",
  "        view.samplerClip = clip.id;",
  "        view.samplerPattern = '';",
  "        view.pendingPattern = '';",
  "        view.samplerPage = 0;",
  "        view.samplerStep = null;",
  "        if (view.stepHold && view.stepHold.timer) clearTimeout(view.stepHold.timer);",
  "        view.stepHold = null;",
  "        view.stepLock = null;",
  "      }",
  "      var banks = banksOfTrack(snap, track.id);",
  "      var bank = bankOf(snap, track.id, view.samplerBank) || banks[0] || null;",
  "      view.samplerBank = bank ? bank.id : '';",
  "      var index = clamp(Math.round(Number(view.samplerPad) || 0), 0, PAD_COUNT - 1);",
  "      view.samplerPad = index;",
  "      var pad = bank ? padOf(snap, track.id, bank.id, index) : null;",
  "",
  "      samplerHost.hidden = false;",
  "      clear(samplerHost);",
  "      samplerHost.appendChild(samplerHeader(snap, clip, track));",
  "",
  "      var body = el('div', 'st-sampler-body');",
  "      var left = el('div', 'st-sampler-pads');",
  "      left.appendChild(el('h3', 'st-sampler-sub', bank ? 'Pads \u00b7 bank ' + String(bank.name) : 'Pads'));",
  "      left.appendChild(bankTabs(track, banks, bank));",
  "      left.appendChild(padGrid(snap, track, bank, index));",
  "      left.appendChild(padTools(snap, track, bank, index));",
  "      body.appendChild(left);",
  "",
  "      var right = el('div', 'st-sampler-right');",
  "      if (view.stepLock) right.appendChild(stepLockStrip(view.stepLock));",
  "      right.appendChild(padSettings(snap, track, bank, pad, index));",
  "      // The chop editor: the waveform with one marker per slice start, the",
  "      // two ways to chop, and Assign slices to pads.",
  "      var chopHost = el('div', 'st-sampler-slot');",
  "      chopHost.setAttribute('data-role', 'sampler-chop');",
  "      chopHost.appendChild(chopEditor(snap, track, bank, pad, index));",
  "      right.appendChild(chopHost);",
  "      // The step sequencer: the clip's patterns and loop, the selected pad's",
  "      // lane of steps, and the chain.",
  "      var stepsHost = el('div', 'st-sampler-slot');",
  "      stepsHost.setAttribute('data-role', 'sampler-steps');",
  "      stepsHost.appendChild(stepsPanel(snap, clip, track, bank, index));",
  "      right.appendChild(stepsHost);",
  "      // The performance effects and the looper: the mockup's six buttons, held",
  "      // rather than clicked, and the capture that turns a loop into a pad.",
  "      var fxHost = el('div', 'st-sampler-slot');",
  "      fxHost.setAttribute('data-role', 'sampler-fx');",
  "      fxHost.appendChild(performancePanel(snap, track, bank, index));",
  "      right.appendChild(fxHost);",
  "      body.appendChild(right);",
  "      samplerHost.appendChild(body);",
  "      // The first draw measures the width its waveform actually has and draws",
  "      // it again with one peak per pixel column of that width.",
  "      if (measureWaveWidth()) { renderSampler(snapshot()); return; }",
  "      // Opening the view is also a moment to make sure every sample its pads",
  "      // play is in the engine: a fetch already done is not repeated.",
  "      if (view.engine) syncSamples(snap);",
  "    }",
  "",
  "    function samplerHeader(snap, clip, track) {",
  "      var head = el('div', 'st-sampler-head');",
  "      head.appendChild(button('st-btn st-small', '\u2190 Session', {",
  "        'data-act': 'close-sampler', title: 'Back to the session grid'",
  "      }));",
  "      head.appendChild(el('h2', 'st-sampler-title', track.name));",
  "      var pattern = shownPatternOf(snap, clip);",
  "      var steps = Math.max(1, Math.round(Number(clip.length_steps) || 16));",
  "      var swing = Math.round((Number(clip.swing) || 0) * 100);",
  "      head.appendChild(el('span', 'st-sampler-meta',",
  "        'Pattern ' + String(pattern ? pattern.name : 'A') + ' \u00b7 ' + String(steps)",
  "        + ' steps \u00b7 swing ' + String(swing) + '%'));",
  "      return head;",
  "    }",
  "",
  "    function bankTabs(track, banks, shown) {",
  "      var row = el('div', 'st-bank-tabs');",
  "      for (var i = 0; i < banks.length; i += 1) {",
  "        var bank = banks[i];",
  "        var on = !!(shown && String(bank.id) === String(shown.id));",
  "        row.appendChild(button('st-toggle' + (on ? ' st-on' : ''), bank.name, {",
  "          'data-act': 'pick-bank', 'data-bank-id': bank.id, 'data-track-id': track.id,",
  "          'aria-pressed': on ? 'true' : 'false',",
  "          title: 'Show this bank of pads'",
  "        }));",
  "      }",
  "      row.appendChild(button('st-btn st-small', '+ Bank', {",
  "        'data-act': 'add-bank', 'data-track-id': track.id, title: 'Add a bank of 16 empty pads'",
  "      }));",
  "      return row;",
  "    }",
  "",
  "    function padGrid(snap, track, bank, selected) {",
  "      var grid = el('div', 'st-pad-grid');",
  "      grid.setAttribute('role', 'group');",
  "      grid.setAttribute('aria-label', 'Pads of ' + String(track.name));",
  "      if (!bank) {",
  "        grid.appendChild(el('p', 'st-empty-note', 'This kit has no bank yet; add one.'));",
  "        return grid;",
