  "      for (var index = 0; index < PAD_COUNT; index += 1) {",
  "        var pad = padOf(snap, track.id, bank.id, index);",
  "        var label = padLabel(bank, index);",
  "        var pending = pendingForPad(track.id, bank.id, index);",
  "        var name = pending ? padPendingText(pending) : padName(snap, pad);",
  "        var node = button('st-pad' + (index === selected ? ' st-pad-sel' : ''), '', {",
