  "          'data-pad-index': String(index),",
  "          'aria-label': label + ' ' + name,",
  "          'aria-pressed': index === selected ? 'true' : 'false',",
  "          title: 'Play this pad; keys 1-8 and Q-I play the sixteen'",
  "        });",
  "        node.appendChild(el('span', 'st-pad-num', label));",
  "        node.appendChild(el('span', 'st-pad-name', name));",
  "        grid.appendChild(node);",
  "      }",
  "      return grid;",
  "    }",
  "",
  "    function padTools(snap, track, bank, index) {",
  "      var box = el('div', 'st-sampler-tools');",
  "      if (bank) {",
  "        var importLabel = el('label', 'st-btn st-small st-import');",
  "        importLabel.appendChild(el('span', '', 'Import a sound'));",
  "        var file = el('input', 'st-file');",
  "        file.type = 'file';",
  "        file.accept = 'audio/*,.wav,.flac,.mp3,.ogg';",
  "        file.setAttribute('data-act', 'sample-import');",
  "        file.setAttribute('data-track-id', track.id);",
  "        file.setAttribute('data-bank-id', bank.id);",
  "        file.setAttribute('data-pad-index', String(index));",
  "        file.setAttribute('aria-label', 'Import a sound onto the selected pad');",
  "        importLabel.appendChild(file);",
  "        box.appendChild(importLabel);",
  "        box.appendChild(button('st-btn st-small' + (view.sampleRec ? ' st-on' : ''),",
  "          view.sampleRec ? 'Stop recording' : 'Record into pad', {",
  "            'data-act': 'pad-record', 'data-track-id': track.id, 'data-bank-id': bank.id,",
  "            'data-pad-index': String(index),",
  "            'aria-pressed': view.sampleRec ? 'true' : 'false',",
  "            title: 'Record the chosen input straight into this pad'",
  "          }));",
  "      }",
  "      // Resample the master mix, or one track's own output, into the pad.",
  "      var select = el('select', 'st-select st-resample-target');",
  "      select.setAttribute('data-act', 'resample-target');",
  "      select.setAttribute('aria-label', 'What to resample');",
  "      var master = el('option', '', 'Master');",
  "      master.value = 'master';",
  "      if (String(view.resampleTarget) === 'master') master.selected = true;",
