  "    function isMixStep(entry) {",
  "      if (!entry || MIX_COMMANDS[String(entry.command)] !== true) return false;",
  "      var refs = Array.isArray(entry.touched) ? entry.touched : [];",
  "      for (var i = 0; i < refs.length; i += 1) {",
  "        var text = String(refs[i]);",
  "        if (text === 'master') continue;",
  "        var at = text.indexOf(':');",
  "        var kind = at > 0 ? text.slice(0, at) : '';",
  "        if (kind === 'insert' || kind === 'send' || kind === 'return' || kind === 'track') continue;",
  "        return false;",
  "      }",
  "      return true;",
  "    }",
  "",
  "    /**",
  "     * The mixer step behind a history entry, or null when its chain of undo/redo",
  "     * entries leads out of this page's history. An undo names the step it took",
  "     * back (undo_of), and a redo names the undo it took back, so the chain is",
  "     * followed to the mixer command the run is made of (see server/history.js).",
  "     */",
  "    function historyRoot(entry) {",
  "      var current = entry;",
  "      var steps = 0;",
  "      while (current && (String(current.command) === 'history.undo' || String(current.command) === 'history.redo')) {",
  "        var at = current.undo_of ? indexOfEntry(String(current.undo_of)) : -1;",
  "        if (at < 0) return null;",
  "        current = view.history[at];",
  "        steps += 1;",
  "        if (steps > 64) return null;",
  "      }",
  "      return current || null;",
