  "    function undoneNow(entry) {",
  "      var current = entry;",
  "      var steps = 0;",
  "      while (current && current.undone_by) {",
  "        var at = indexOfEntry(String(current.undone_by));",
  "        // An undo this page cannot see (a trimmed history) is one that took the",
  "        // step back: the step is not part of the pass any more.",
