  "     * agent. The bookkeeping steps that take one of the pass's own steps back are",
  "     * skipped (that step is gone, and the steps before it are still the pass), and",
  "     * anything else — another agent, the operator, a step outside the mixer —",
  "     * ends the run. A redo is part of the pass its target belongs to, and never",
  "     * cuts the run in two.",
  "     */",
  "    function mixerPass() {",
  "      var entries = [];",
  "      var author = null;",
  "      for (var i = 0; i < view.history.length; i += 1) {",
  "        var entry = view.history[i];",
  "        if (!entry) continue;",
  "        var command = String(entry.command || '');",
  "        // The history's own bookkeeping steps: history.undo and history.redo",
  "        // (see server/history.js). One of them takes a step of the pass itself",
  "        // back (or puts it back), so the run carries on past it; anything else",
  "        // ends the run.",
  "        if (command === 'history.undo' || command === 'history.redo') {",
  "          var root = historyRoot(entry);",
  "          if (root && isMixStep(root)) continue;",
  "          break;",
  "        }",
  "        if (!isMixStep(entry)) break;",
  "        if (!entry.author || entry.author.kind === 'human') break;",
  "        if (!author) author = entry.author;",
  "        else if (String(entry.author.id) !== String(author.id)) break;",
