  "      if (!pass) return refs;",
  "      for (var i = 0; i < pass.entries.length; i += 1) {",
  "        var touched = Array.isArray(pass.entries[i].touched) ? pass.entries[i].touched : [];",
  "        for (var r = 0; r < touched.length; r += 1) refs[String(touched[r])] = true;",
  "      }",
  "      return refs;",
  "    }",
  "",
  "    /** Whether a chain wears the pass's outline: its own ref, or one of its effects. */",
  "    function chainInPass(refs, owner, inserts) {",
  "      if (!refs) return false;",
  "      if (refs[String(owner)] === true) return true;",
  "      for (var i = 0; i < inserts.length; i += 1) {",
  "        if (refs['insert:' + String(inserts[i].id)] === true) return true;",
  "      }",
  "      return false;",
  "    }",
  "",
  "    /** Whether one track's strip wears the outline, its sends included. */",
  "    function trackInPass(refs, trackId, inserts) {",
  "      if (chainInPass(refs, 'track:' + String(trackId), inserts)) return true;",
  "      if (!refs) return false;",
