  "          if (!Object.prototype.hasOwnProperty.call(params, name)) continue;",
  "          var sentKey = 'mixparam:' + id + ':' + name;",
  "          if (view.mix.sent[sentKey] === undefined) continue;",
  "          if (String(params[name]) === view.mix.sent[sentKey]) continue;",
  "          delete view.mix.sent[sentKey];",
  "        }",
  "        var was = view.mix.marks[id];",
  "        if (was === undefined || was === seen[id]) continue;",
  "        delete view.mix.faults[id];",
  "        delete view.mix.loading[id];",
  "        delete view.mix.loadingAt[id];",
