  "      dot.style.background = AGENT;",
  "      box.appendChild(dot);",
  "      box.appendChild(el('p', 'st-mix-banner-text', mixPassText(pass)));",
  "      var running = !!(view.mix.pass && view.mix.pass.running === true);",
  "      var comparing = view.mix.compare.active === true;",
  "      var ab = button('st-btn st-small', comparing ? MIX_AB_AFTER_TEXT : MIX_AB_BEFORE_TEXT, {",
  "        'data-act': 'mix-ab',",
  "        title: comparing",
  "          ? 'Play the mix as it is now'",
  "          : 'Play the song as it was before this pass, without changing it'",
  "      });",
  "      ab.setAttribute('aria-pressed', comparing ? 'true' : 'false');",
  "      box.appendChild(ab);",
  "      var undo = button('st-btn st-small', running ? MIX_UNDOING_TEXT : MIX_UNDO_PASS_TEXT, {",
  "        'data-act': 'mix-undo-pass',",
