  "    var askLog = null;",
  "",
  "    // Keyed by song AND bot: if the project's bot changes, the old session is not reused.",
  "    function askKey() {",
  "      var bot = view.projectBot;",
  "      return ASK_KEY + activeSongId + ':' + (bot && bot.id ? bot.id : '');",
  "    }",
  "",
  "    function askBriefing() {",
