  "      var stored = askStored();",
  "      var sid = view.askSession || (stored ? stored.sid : '');",
  "      if (sid) askRemember(sid, true);",
  "    }",
  "",
  "    // The transcript under the box. It is built here rather than in the",
  "    // handler's markup because it is live state: this session owns it, and",
  "    // teardown removes it again so a cached page carries no reply text.",
  "    function askLine(text) {",
