  "      if (!value) return;",
  "      if (!askLog) {",
  "        askLog = el('div', 'st-ask-log');",
  "        askLog.setAttribute('data-role', 'ask-log');",
  "        askLog.style.fontSize = '12px';",
  "        askLog.style.lineHeight = '1.45';",
  "        var box = askInput ? askInput.parentNode : null;",
  "        if (box && box.parentNode) box.parentNode.insertBefore(askLog, box.nextSibling);",
  "      }",
  "      // A long conversation costs one node per reply, so the oldest go.",
  "      while (askLog.childNodes.length >= 12) askLog.removeChild(askLog.firstChild);",
  "      var line = el('p', 'st-ask-line', value);",
  "      line.style.margin = '6px 0 0';",
  "      askLog.appendChild(line);",
  "    }",
  "",
  "    // One plain sentence for a refusal, whichever step produced it.",
  "    function askFailure(status, body) {",
  "      var bot = view.projectBot || { name: 'The bot' };",
  "      var code = body && typeof body.error === 'string' ? body.error : '';",
  "      // A turn the bot is still on: the session is fine, the question is early.",
  "      if (status === 409 && code === 'turn_in_progress') return bot.name + ' is still answering\\u2026';",
  "      if (status === 409 && code === 'engine_required') return 'The bot engine is not running.';",
  "      if (status === 403 && code === 'perch_not_attached') {",
