  "",
  "    function askPost(path, body) {",
  "      var headers = { 'content-type': 'application/json' };",
  "      var token = cookie('crow_csrf');",
  "      if (token) headers['x-crow-csrf'] = token;",
  "      return fetch(ASK_API + path, {",
  "        method: 'POST',",
  "        credentials: 'same-origin',",
  "        headers: headers,",
  "        body: JSON.stringify(body)",
