  "      if (!text.trim() || text === view.askLast) return;",
  "      view.askLast = text;",
  "      askLine(text);",
  "    }",
  "",
  "    // Drop the session and its stream: a stopped session cannot be messaged,",
  "    // so the next question spawns a fresh one. The remembered id",
  "    // goes with it — it is only reused while it still answers 2xx.",
  "    function askEnd() {",
  "      if (view.askStream) {",
