  "    }",
  "",
  "    function openAskStream(sid) {",
  "      if (view.askStream || typeof window.EventSource !== 'function') return;",
  "      var source = new window.EventSource(ASK_API + '/interactive/' + encodeURIComponent(sid) + '/events');",
  "      view.askStream = source;",
