  "    }",
  "",
  "    function askSessionId() {",
  "      if (view.askSession) return Promise.resolve(view.askSession);",
  "      if (view.askStarting) return view.askStarting;",
  "      var bot = view.projectBot;",
  "      if (!bot) return Promise.reject(new Error('No project bot is connected.'));",
  "      // A session this tab already opened for this song is reused as it is:",
  "      // the message that follows is what tells us whether the gateway still",
  "      // has it (a 404 or 410 drops it — see askDeliver).",
  "      var stored = askStored();",
  "      if (stored) {",
  "        view.askSession = stored.sid;",
  "        openAskStream(stored.sid);",
  "        return Promise.resolve(stored.sid);",
  "      }",
  "      // No session yet: the first question spawns a new one, and every later",
  "      // question is a message on it.",
  "      // The value true is the only form the route honours; it rebuilds the",
  "      // project briefing on the server and reads no text from here, which is",
