  "        throw err;",
  "      });",
  "      return view.askStarting;",
  "    }",
  "",
  "    function askSend() {",
  "      if (!view.projectBot || !askInput || askInput.disabled) return;",
  "      var text = String(askInput.value || '').trim();",
  "      if (!text) return;",
  "      askInput.value = '';",
