  "        });",
  "    }",
  "",
  "    // The song's project bot, asked once when the page boots. No bot leaves",
  "    // the box exactly as the handler rendered it: disabled, saying so.",
  "    function loadProjectBot() {",
  "      fetch('/api/studio/songs/' + encodeURIComponent(activeSongId) + '/project-bot', {",
  "        credentials: 'same-origin'",
  "      })",
  "        .then(function (response) { return response.ok ? response.json() : null; })",
  "        .then(function (data) {",
