  "",
  "    // ---- boot ----------------------------------------------------------",
  "",
  "    // Turbo fires turbo:visit in the same task as turbo:before-visit when a",
  "    // visit really starts. If it never arrives, the page stayed put (the",
  "    // visit was cancelled or rerouted to a full load), so the shell this",
  "    // teardown left is booted again instead of being shown empty.",
  "    function onBeforeCache() {",
  "      teardown();",
  "    }",
  "",
  "    function onBeforeVisit() {",
  "      visitStamp.started = false;",
  "      teardown();",
  "      setTimeout(function () {",
  "        if (visitStamp.started) return;",
  "        if (page.__studioSession === session) return;",
  "        if (typeof page.__studioBoot === 'function') page.__studioBoot();",
  "      }, 0);",
  "    }",
  "",
  "    loadModules();",
  "    loadProjectBot();",
  "    connect();",
  "    // The controllers: this page listens from its own boot, and opens the access",
  "    // again only when this browser already granted it.",
  "    midiStart();",
  "    // The audio inputs this device offers, and the takes it still owes the",
  "    // gateway: both are read once, and the pending ones are resumed.",
  "    loadInputs().then(function () { if (!view.closed) render(); });",
  "    resumePending();",
  "    projectIdFor();",
  "    page.addEventListener('click', onClick);",
  "    page.addEventListener('change', onChange);",
  "    page.addEventListener('input', onInput);",
  "    page.addEventListener('pointerdown', onPointerDown);",
  "    // pointerup alone leaves a deferred render waiting forever after a",
