  "    document.addEventListener('dblclick', onDoubleClick);",
  "    document.addEventListener('turbo:before-visit', onBeforeVisit);",
  "    document.addEventListener('turbo:before-cache', onBeforeCache);",
  "",
  "    // A pending new clip that never lands (a refusal, a dropped socket)",
  "    // must not keep a focus that blocks the agent forever.",
  "    view.tick = setInterval(function () {",
  "      if (view.pendingSelect && !snapshot().clips[view.pendingSelect]) {",
  "        view.pendingSelect = null;",
  "        if (view.selectedClipId) {",
  "          view.selectedClipId = null;",
  "          view.selectedNote = -1;",
  "          sendFocus(null);",
  "          render();",
  "        }",
  "      }",
  "    }, 5000);",
  "",
  "    function loadModules() {",
  "      fetch('/api/studio/module-types', { credentials: 'same-origin' })",
  "        .then(function (response) { return response.ok ? response.json() : null; })",
  "        .then(function (data) {",
  "          if (!data) return;",
  "          view.generators = Array.isArray(data.generators) ? data.generators : [];",
  "          view.modules = data.modules && typeof data.modules === 'object' ? data.modules : {};",
  "          render();",
  "        })",
  "        .catch(function () {",
  "          // The grid works without the catalogue; only the pickers stay plain.",
  "        });",
  "    }",
  "",
  "    // Turbo swaps the page body, and a document may register only ONE import",
  "    // map, before its first module load. This page's map has to travel in the",
  "    // body beside the script (a bundle cannot write into the dashboard's",
  "    // head), so a second Studio page reached by Turbo cannot register it again",
  "    // and Yjs's bare lib0 imports may stop resolving. A map cannot be",
  "    // registered twice or replaced, so the repair is a real page load: say so,",
